<script setup lang="ts">
import { PhBuildings, PhCheckCircle, PhHourglass, PhProhibit, PhXCircle } from '@phosphor-icons/vue'
import { normalizeApiError } from '~/utils/api/errors'
import { platformPatch, platformGet } from '~/utils/auth/platformClient'
definePageMeta({ layout: 'platform', middleware: 'platform-auth' }); useHead({ title: 'Hospital tenants' })
type Tenant = { id: string; slug?: string; name?: string; contact_email?: string; lifecycle_status?: string; rejection_reason?: string; created_at?: string }
const tabs = [{ id: 'pending_approval', label: 'Pending', icon: PhHourglass }, { id: 'active', label: 'Active', icon: PhCheckCircle }, { id: 'suspended', label: 'Suspended', icon: PhProhibit }, { id: 'rejected', label: 'Rejected', icon: PhXCircle }, { id: '', label: 'All', icon: PhBuildings }]
const selectedTab = ref('pending_approval'); const tenants = ref<Tenant[]>([]); const loading = ref(false); const error = ref(''); const busyId = ref(''); const confirm = ref<{ action: string; tenant: Tenant } | null>(null); const rejectReason = ref('')
const lifecycle = (status?: string) => String(status || '').toLowerCase().replace(/_/g, ''); const label = (status?: string) => lifecycle(status) === 'pendingapproval' ? 'pending approval' : lifecycle(status) || 'unknown'; const date = (value?: string) => value ? new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : '—'
const load = async () => { loading.value = true; error.value = ''; try { tenants.value = await platformGet<Tenant[]>('/platform/tenants', selectedTab.value ? { status: selectedTab.value } : undefined) } catch (cause) { error.value = normalizeApiError(cause, 'Platform API unavailable.'); tenants.value = [] } finally { loading.value = false } }
const runAction = async (tenant: Tenant, action: string, body?: Record<string, unknown>) => { busyId.value = tenant.id; try { await platformPatch(`/platform/tenants/${tenant.id}/${action}`, body); confirm.value = null; rejectReason.value = ''; await load() } catch (cause) { error.value = normalizeApiError(cause, 'Tenant action failed.') } finally { busyId.value = '' } }
const confirmAction = () => { if (!confirm.value) return; runAction(confirm.value.tenant, confirm.value.action, confirm.value.action === 'reject' ? { reason: rejectReason.value.trim() || 'Does not meet criteria' } : undefined) }
watch(selectedTab, load); onMounted(load)
</script>
<template><PlatformShell><section class="platform-tenants-page"><div class="platform-page-heading"><div><p class="platform-eyebrow">Platform administration</p><h1>Hospital tenants</h1><p>Review registrations and manage tenant lifecycle.</p></div><span class="platform-count">{{ tenants.length }} shown</span></div><div v-if="error" class="platform-error-banner">{{ error }} <button type="button" @click="load">Retry</button></div><nav class="platform-tabs" aria-label="Tenant status"><button v-for="tab in tabs" :key="tab.id || 'all'" type="button" :class="{ active: selectedTab === tab.id }" @click="selectedTab = tab.id"><component :is="tab.icon" :size="16" /> {{ tab.label }}</button></nav><div v-if="loading" class="platform-tenants-state">Loading tenants…</div><div v-else-if="!tenants.length" class="platform-tenants-empty"><PhHourglass :size="42" weight="duotone" /><strong>{{ selectedTab === 'pending_approval' ? 'No hospitals awaiting approval' : 'No tenants in this queue' }}</strong><p v-if="selectedTab === 'pending_approval'">New registrations will appear here.</p><button v-if="selectedTab === 'pending_approval'" type="button" class="platform-secondary-button" @click="selectedTab = 'active'">View active hospitals</button></div><div v-else class="platform-tenant-list"><article v-for="tenant in tenants" :key="tenant.id" class="platform-tenant-card"><div class="platform-tenant-info"><div class="platform-tenant-title"><strong>{{ tenant.name || 'Unnamed hospital' }}</strong><span :class="`platform-status-${lifecycle(tenant.lifecycle_status)}`">{{ label(tenant.lifecycle_status) }}</span></div><small>{{ tenant.slug || '—' }} · {{ tenant.contact_email || 'No contact email' }}</small><small>Registered {{ date(tenant.created_at) }}<template v-if="tenant.rejection_reason"> · {{ tenant.rejection_reason }}</template></small></div><div class="platform-tenant-actions"><template v-if="lifecycle(tenant.lifecycle_status) === 'pendingapproval'"><button type="button" class="platform-primary-button" :disabled="busyId === tenant.id" @click="confirm = { action: 'approve', tenant }">Approve</button><button type="button" class="platform-danger-button" :disabled="busyId === tenant.id" @click="confirm = { action: 'reject', tenant }; rejectReason = ''">Reject</button></template><button v-else-if="lifecycle(tenant.lifecycle_status) === 'active'" type="button" class="platform-danger-button" :disabled="busyId === tenant.id" @click="confirm = { action: 'suspend', tenant }">Suspend</button><button v-else-if="lifecycle(tenant.lifecycle_status) === 'suspended'" type="button" class="platform-primary-button" :disabled="busyId === tenant.id" @click="runAction(tenant, 'activate')">Reactivate</button></div></article></div></section><div v-if="confirm" class="platform-modal-backdrop" @click.self="confirm = null"><form class="platform-modal" @submit.prevent="confirmAction"><h2>{{ confirm.action === 'approve' ? 'Approve hospital?' : confirm.action === 'reject' ? 'Reject registration?' : 'Suspend hospital?' }}</h2><p>{{ confirm.tenant.name }} will be {{ confirm.action === 'approve' ? 'activated' : confirm.action === 'reject' ? 'rejected' : 'suspended' }}.</p><label v-if="confirm.action === 'reject'">Reason<input v-model="rejectReason" placeholder="Optional reason" /></label><div class="platform-modal-actions"><button type="button" class="platform-secondary-button" @click="confirm = null">Cancel</button><button type="submit" :class="confirm.action === 'reject' || confirm.action === 'suspend' ? 'platform-danger-button' : 'platform-primary-button'" :disabled="busyId === confirm.tenant.id">Confirm</button></div></form></div></PlatformShell></template>
